import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    m = re.match(r"([A-Z]+)(\d+)", ref)
    letters = m.group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1

with zipfile.ZipFile("budget.xlsx") as z:
    names = z.namelist()
    print("ZIP CONTENTS:", names)

    # shared strings
    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    # workbook sheets
    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = []
    for s in wb_root.findall(".//m:sheets/m:sheet", NS):
        sheets.append((s.get("name"), s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")))

    # rels
    rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {}
    for rel in rels_root.findall("{http://schemas.openxmlformats.org/package/2006/relationships}Relationship"):
        rel_map[rel.get("Id")] = rel.get("Target")

    print("\nSHARED STRINGS:", shared)
    print("\nSHEETS (name, rel):", sheets)

    for name, rid in sheets:
        target = rel_map[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target
        print(f"\n=== SHEET: {name} ({target}) ===")
        sroot = ET.fromstring(z.read(target))
        sd = sroot.find("m:sheetData", NS)
        if sd is None:
            print("(empty)")
            continue
        for row in sd.findall("m:row", NS):
            vals = {}
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("m:v", NS)
                is_ = c.find("m:is", NS)
                if t == "s" and v is not None:
                    val = shared[int(v.text)]
                elif t == "inlineStr" and is_ is not None:
                    val = "".join(tt.text or "" for tt in is_.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                elif v is not None:
                    val = v.text
                else:
                    val = ""
                vals[col_to_idx(ref)] = val
            if vals:
                maxc = max(vals)
                print([vals.get(i, "") for i in range(maxc + 1)])

