import zipfile
import re
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

def col_to_idx(ref):
    letters = re.match(r"([A-Z]+)", ref).group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1

with zipfile.ZipFile("budget.xlsx") as z:
    sroot = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))
    rows = []
    for row in sroot.find("m:sheetData", NS).findall("m:row", NS):
        vals = {}
        for c in row.findall("m:c", NS):
            v = c.find("m:v", NS)
            if v is not None:
                vals[col_to_idx(c.get("r"))] = v.text
        rows.append(vals)

def num(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return None

# Expenses section: starts after the "EXPENSES" header, ends before "Total Expenses"
expense_rows = []
in_expenses = False
category_totals = {}
for r in rows:
    a = r.get(0, "")
    b = r.get(1, "")
    c = r.get(2, "")
    if a == "EXPENSES":
        in_expenses = True
        continue
    if in_expenses:
        if a == "Total Expenses":
            break
        if a:
            category_totals.setdefault(a, 0.0)
        n = num(c)
        if n is not None:
            category_totals[a] += n
            expense_rows.append((a, b, n))

print("Expense line items:")
for cat, item, amt in expense_rows:
    print(f"  {cat:15s} {item:20s} {amt:,.2f}")
print()
for cat, tot in category_totals.items():
    print(f"Category total: {cat:15s} {tot:,.2f}")
print(f"\nTOTAL EXPENSES: {sum(category_totals.values()):,.2f}")

# Income section for context
income_rows = []
in_income = False
for r in rows:
    a = r.get(0, "")
    b = r.get(1, "")
    if a == "INCOME":
        in_income = True
        continue
    if in_income:
        if a == "Total Income":
            break
        if a:
            n = num(b)
            income_rows.append((a, n))
income_total = sum(n for _, n in income_rows if n is not None)
print(f"\nTOTAL INCOME: {income_total:,.2f}")
print(f"BALANCE (income - expenses): {income_total - sum(category_totals.values()):,.2f}")

